-- Platsbeskrivningar, omgång 4 (34 platser). Skrivna utifrån platsernas egna hemsidor.
-- Kort text högst 7 ord, lång 70–100 ord.
begin;
update public.places set short_description = 'Butik med växter och lantlig inredning', description = 'Karl Fredrik på Eklaholm är en butik på en gård nära Löderup, där trädgård, blommor och inredning möts. Här finns ett noga utvalt sortiment av växter, blommor, krukor, inredningsdetaljer och presenter, handplockat med känsla för kvalitet, färg och form. Sortimentet ändras med säsongerna. Tanken är att väcka lusten att skapa, odla och omge sig med saker som gör vardagen lite vackrare. För den som inte kan komma till gården finns en webbutik som alltid är öppen.' where id = 193; -- Karl Fredrik på Eklaholm
update public.places set short_description = 'Bageri som bakat sedan 1885', description = 'Mellbybagaren har bakat på Österlen sedan 1885 och har sålt sin Mellbykavring i över hundra år. Kavringen bakas i en lång process: rent rågmjöl skållas och får stå över natten med surdeg, och dagen efter tillsätts jäst, salt, sirap och mer rågmjöl. Bröden bakas två och två, ett ovanpå det andra, och därför finns både ovan- och underkavring. Här bakas även klassiska bröd, vetebröd, kakor och tårtor för alla tillfällen. Bageriet har en lång familjehistoria som går tillbaka till 1800-talet.' where id = 195; -- Mellbybagaren 
update public.places set short_description = 'Stor inredningsbutik med karaktär i Borrby', description = 'Apotekarns är en inredningsbutik på 1200 kvadratmeter på Kärrgatan i Borrby. Butiken startade 2012 i en trädgård bakom ett gammalt apotek i Simrishamn och har sedan dess vuxit till dagens stora lokal. Här finns handplockade föremål med historia och känsla: färg, form, textil, doft, möbler och detaljer för sovrum, vardagsrum och andra rum i hemmet. Tanken är att hjälpa till att skapa hem med mer själ, värme och personlighet. Butiken har öppet fredag till söndag.' where id = 196; -- Apotekarns 
update public.places set short_description = 'Akvarellgalleri och ateljé med kurser', description = 'Ateljé Gamlegård är konstnären Monica Kjellmans ateljé och galleri på Österlen, utanför Simrishamn. I galleriet visas ett nittiotal akvareller i olika stilar, med motiv som landskap, växtlighet, byggnader och människor. Här finns också konstkort till försäljning. I ateljén håller Monica kurser i akvarellmålning för den som vill lära sig mer. Aktuella öppettider och kommande kurser finns på hemsidan, och den som vill komma på besök eller köpa en målning kan också höra av sig direkt till Monica via telefon eller mejl.' where id = 199; -- Ateljé Gamlegård Österlen
update public.places set short_description = 'Keramikverkstad med drejkurser i Borrby', description = 'Lerbruket Borrby är en keramikverkstad och butik på Köpmangatan i Borrby som har säsongsöppet under sommaren. Här kan man prova på att dreja, gå på workshops och arbeta i öppen verkstad. För barn mellan 6 och 14 år finns sommarlovskeramik, där barnen under två tillfällen bygger, formar och skapar med lera. I butiken säljs keramik och andra unika saker att ta med hem. Programmet uppdateras löpande på hemsidan och på Instagram, och drejkurserna bokas i förväg.' where id = 200; -- Lerbruket Borrby
update public.places set short_description = 'Galleri med Falkåkes konst och design', description = 'Korrebo Galleri i Sankt Olof drivs av Christer Falk och visar och säljer konst, keramik och skulptur av konstnären Falkåke, med verk från 1950-talet och framåt. Här finns också redesign och design, nostalgiprylar och verk av externa utställare. Galleriet har öppet några dagar varje månad, och aktuella datum finns på hemsidan. Den som vill komma på besök vid andra tider kan höra av sig via sms eller mejl. Galleriet deltar också i konstrundan på Österlen.' where id = 202; -- Korrebo Galleri
update public.places set short_description = 'Butik och galleri i gammalt stall', description = 'Qalops Butik & Galleri ligger i Simrishamn i en ljus lokal med stallfönster, grovputsade vita väggar och stockar i taket. På väggarna hänger konst av flera olika utställare, och konsten säljs i galleriet. I butiken finns saker som ägarna själva tycker om: gamla saker med en historia, nya saker som sticker ut och lokala produkter. Ägarna har ett stort intresse för odling och säljer även bokashi, ett sätt att kompostera matavfall. Det finns också en webbshop.' where id = 203; -- Qalops Butik & Galleri
update public.places set short_description = 'Annika Jägfeldts rockkonst i Löderup', description = 'Galleri Jägfeldt i Löderup är konstnären Annika Jägfeldts galleri. Annika är utbildad vid Konstfack i Stockholm och medlem i Konstnärernas Riksorganisation. Hon målar ofta porträtt av rockartister, och hennes verk kombinerar traditionella metoder med moderna influenser. Man kan beställa ett eget artistporträtt via telefon eller mejl. Hennes konst visas även på andra gallerier. Galleriet har öppet enligt överenskommelse, så det är bäst att höra av sig innan besöket, och nyheter läggs ut på Instagram och Facebook.' where id = 204; -- Galleri Jägfeldt
update public.places set short_description = 'Skulptur, måleri och poesi i Peppinge', description = 'Galleri Peppinge är konstnären Åsa Melins galleri på Peppingevägen, mellan Kåseberga och Valleberga på södra Österlen. Här visas Åsas skulptur, måleri och poesi. Galleriet har öppet på lördagar och söndagar under eftermiddagen, och utöver det går det bra att komma andra dagar efter överenskommelse. Den som vill boka en tid för besök kan ringa eller sms:a direkt till Åsa. Galleriet har också en Facebooksida där nyheter och aktuella öppettider läggs ut. Galleriet ligger nära flera andra ateljéer i trakten.' where id = 205; -- Galleri Peppinge 
update public.places set short_description = 'Konsthall från 1965 i Tomelilla', description = 'Tomelilla konsthall byggdes 1965 och var en av Sveriges första konsthallar på landsbygden. Konsthallen visar flera utställningar om året med olika konstnärer, och ofta pågår olika utställningar på två plan samtidigt. Här ordnas vernissager, visningar och andra program, till exempel under kulturnatten. Utställningarna byts ut med jämna mellanrum, så det finns ofta något nytt att se. Aktuella och kommande utställningar och öppettider finns på konsthallens hemsida. Konsthallen ligger mitt i Tomelilla.' where id = 206; -- Tomelilla Konsthall
update public.places set short_description = 'Keramikateljé på Bragebacka Gård', description = 'Monica Persdotter är keramiker och har sin ateljé, verkstad och utställning på Bragebacka Gård strax ovanför Gislövshammar. Hon var lärling hos keramikern Calle Forsberg i Stockholm från 2011 och flyttade till Österlen 2018. Monica arbetar främst med stengods. Sedan hösten 2023 tar hon fram och producerar keramiken som används på Daniel Berlins restaurang Vyn. Under sommaren ställer hon ut i ett litet grishus på gården. Öppettider och nya verk läggs ut på Instagram, där man också kan höra av sig.' where id = 207; -- Monica Persdotter Keramik & Form
update public.places set short_description = 'Lokalt tillverkade soffor och sängar', description = 'Österlen Inredning designar och tillverkar möbler med hjärtat på Österlen och naturen som inspiration. Alla möbler tillverkas i Sverige i nära samarbete med underleverantörer, med stort fokus på kvalitet och hållbarhet. Sortimentet består framför allt av soffor, bäddsoffor och sängar, och många av dem är döpta efter platser på Österlen, som Simris, Kåseberga och Spjutstorp. Här finns även en soffa gjord helt i naturmaterial. Visionen är att möblerna ska hålla länge och kunna användas i generationer.' where id = 209; -- Österlen Inredning
update public.places set short_description = 'Inredning, antik och homestyling i Borrby', description = 'Kringstad Interiör är en design- och inredningsbutik i Borrby som värnar om det tidlösa, det återanvända och det ombonade hemmet. I butiken säljs möbler, heminredning, antika möbler, konst, ljus, fårskinn och textilier, både från Österlen och från andra håll. Kringstad Interiör arbetar också med homestyling och inredningsdesign, renoverar möbler och förmedlar antikviteter. Sortimentet finns även i en webbutik, där man till exempel hittar linnehanddukar, kuddar och filtar. Butiken passar för den som vill skapa ett varmt och personligt hem.' where id = 210; -- Kringstad Interiör
update public.places set short_description = 'Bed and breakfast och lägenhet vid Kåseberga', description = 'Ales BnB är ett nystartat bed and breakfast precis utanför Kåseberga, som drivs av ett par som flyttade hit från Uppsala. Här finns tre dubbelrum med egen dusch och toalett och ett gemensamt kök och vardagsrum. Det finns också en lägenhet med två sovrum, eget kök och badrum, som hyrs ut veckovis. Ales BnB erbjuder vandring på egen hand, med boende och planerade rutter, för den som vill upptäcka naturen i lugn takt. På hemsidan finns även tips om vad man kan göra och äta på Österlen.' where id = 228; -- Ales BnB
update public.places set short_description = 'Krukmakeri och galleri i Hammenhög', description = 'Maria Ekberg Keramik är ett krukmakeri med galleri på Ystadsvägen i Hammenhög. Maria är krukmakarmästare och gör handgjord, unik keramik, där inget föremål blir det andra likt. Hon arbetar bland annat med vedbränning, och åker ibland utomlands på keramikworkshops, till exempel till Sydkorea. Galleriet har inga fasta öppettider under hösten, men det går bra att komma på besök efter överenskommelse. Den som har frågor eller vill beställa något kan höra av sig via telefon eller mejl. På hemsidan berättar Maria om sitt skapande.' where id = 229; -- Maria Ekberg Keramik
update public.places set short_description = 'Grill, fisk och pizza i Simrishamn', description = 'Restaurang Cimbris i Simrishamn serverar medelhavsinspirerade grillrätter, lokala fiskrätter och italienska pizzor. Restaurangen drivs av två vänner med lång erfarenhet från restaurangbranschen, bland annat från Brösarps Gästgifveri. De vill att varje måltid ska bli minnesvärd, och håller gärna öppet så länge gästerna sitter kvar. Cimbris har utsetts till People''s Choice under matfestivalen Moveat i Simrishamn. Restaurangen är en del av Semester Sam, som samlar verksamheter inom mat och upplevelser. Bord bokas via hemsidan.' where id = 231; -- Resturang Cimbris
update public.places set short_description = 'Handgjord porslinskeramik från egen ateljé', description = 'Anna-Carin Dahl Design gör keramik av fint vitt porslin för vardag och glädje, och har arbetat med keramik sedan 1993. Sedan 2006 driver hon sitt eget designföretag i Glemmingebro, där allt sköts från den egna ateljén: produktutveckling, tillverkning och försäljning. Varje föremål görs för hand av henne själv. I sortimentet finns bland annat ljuslyktor som kastar skuggor av dekorationer genom porslinet och små skålar, en för varje veckodag. Föremålen är tåliga och håller i många år. Keramiken säljs i webbutiken och i ateljén.' where id = 233; -- Anna-Carin Dahl Design 
update public.places set short_description = 'Ateljé och butik med möbler och keramik', description = 'Örum 370 är en ateljé och butik i Örum nära Löderup, med möbler och keramik att ha både inne och ute. Den drivs av keramikern Sven Lagerwall och arkitekten och formgivaren Lillian Öberg, som ställer ut och säljer sina egna verk. Här finns allt från muggar till bord, unika objekt och lokalt producerade saker. Under evenemanget Österlen Lyser i början av november möblerar de med ljuspunkter och installationer både ute och inne. Aktuella öppettider finns på deras hemsida.' where id = 235; -- Örum 370 Keramik 
update public.places set short_description = 'Thailändsk restaurang på torget i Tomelilla', description = 'Thai Garden ligger på torget i Tomelilla och har serverat thailändsk mat sedan 2006. Konceptet är en kombination av det asiatiska köket, med färska råvaror som wokas för att behålla den krispiga konsistensen och den autentiska smaken. Restaurangen erbjuder servering på plats, avhämtning och lunchbuffé några dagar i veckan, och har fullständiga rättigheter. Öppettiderna är längre under sommaren än under resten av året, och vissa helgdagar är det stängt. Bord och avhämtning beställs på telefon.' where id = 236; -- Thai Garden Tomelilla
update public.places set short_description = 'Handgjord keramik i Hörup', description = 'Annika Äikäs Keramik är en verkstad och butik i den lilla byn Hörup, ungefär två mil öster om Ystad, i anslutning till Annikas hem. Annika gör handgjord keramik i egen design, både bruksföremål i mindre serier och unikt konsthantverk. Hon arbetar i stengods och högbränt lergods som tål både diskmaskin och mikrovågsugn. Annika har haft egen verkstad och butik sedan 1994 och har utbildat sig i konsthantverk i Glimåkra. Nyheter och aktuella öppettider läggs ut på hennes Facebooksida.' where id = 237; -- Annika Äikäs Keramik
update public.places set short_description = 'Boende på lantgård och vid havet', description = 'Borrby Kungsgård är ett personligt boende i hjärtat av Österlen, som drivs av familjen Brinte. Uppe på gården bor man i karaktärsfulla hus som Brygghuset, Svinhuset och Undantaget, med en stor trädgård för lek, spel och vila. Gårdens aktiviteter brukar vara populära, och solnedgången ackompanjeras av klockringningen från Borrby kyrka. Nere vid havet finns de nybyggda Skyttepaviljongen och Hemvärnsgården, och en kort skogspromenad bort ligger Borrby strand. Henric är heltidsbonde på gården.' where id = 239; -- Borrby Kungsgård
update public.places set short_description = 'Keramikverkstad, galleri och butik sedan 1995', description = 'Keramika Fantasia grundades 1995 av Eva Troedson och har en verkstad, ett galleri och en butik nära Bollerup. Här skapas handgjord keramik där varje verk är unikt, inspirerat av Österlens skönhet. I sortimentet finns bland annat trädgårdsspjut. Butiken har öppet de flesta dagar under sommaren. Det finns ingen webbshop, men det går att beställa och få keramiken skickad med posten, utom trädgårdsspjuten. Man kan också köpa presentkort. Vägbeskrivning finns på hemsidan, och beställningar görs enklast på telefon.' where id = 240; -- Keramika Fantasia
update public.places set short_description = 'Familjedrivet krukmakeri sedan 1975', description = 'Argilla är ett familjedrivet krukmakeri nära Kåseberga som grundades 1975. Namnet betyder vit lera eller krukmakarlera på latin. Krukmakaren Anders Hägg sköter all tillverkning, ibland med hjälp av Madeleine. Anders utbildade sig till krukmakare på Östra Grevie och har varit mästare sedan 1975. Han arbetar enbart med blyfritt stengods och gör allt för hand, och allt drejas. För information om öppettider och för att beställa är det bäst att ringa eller mejla. Krukmakeriet har även en Facebooksida.' where id = 241; -- Argilla Krukmakeri Keramik
update public.places set short_description = 'Växter och lantlig inredning i gammalt svinstall', description = 'Allevadstorp Trädgård & Interiör är ett lokalt familjeföretag mitt emellan Ystad och Tomelilla, vid Högestad-korset. Butiken ligger i ett gammalt svinstall på familjens fyrlängade gård, där de bor med barn, hästar, hund och kaniner. Här säljs växter och inredningsföremål i lantlig stil, och sortimentet är noga utvalt eftersom familjen bara säljer det de själva skulle vilja ha hemma. Butiken har öppet onsdag till söndag. Naturen och det goda livet på landet är en stor del av känslan.' where id = 243; -- Allevadstorp Trädgård & Interiör
update public.places set short_description = 'Designbutik och inredningsarkitekt vid Stenshuvud', description = 'Engberg Interior Design är en personlig designbutik och studio för inredningsarkitektur intill Stenshuvud, granne med bokskog, stränder, hästar och höns. Sortimentet består av handplockade skandinaviska märken med fokus på estetik, hantverk, materialkänsla och hållbarhet. Allt är tillverkat i hög kvalitet och i små serier. Här finns bland annat bomullskläder från danska Aiayu, linnetextilier från Libeco, massiva trämöbler från skandinaviska snickerier och väskor från Mismo. Ägaren arbetar även som inredningsarkitekt med uppdrag åt kunder.' where id = 244; -- Engberg Interior Design
update public.places set short_description = 'Butik för hem och trädgård med boende', description = 'Jansro Hem & Trädgård ligger på Arnhög Farm vid Övre Kustvägen i Örnahusen, strax söder om Skillinge. I butiken finns ett stort utbud av personligt utvalda ting för hem och trädgård, växter, kläder och accessoarer, både inne och utanför den lilla butiken på landet. På gården finns också fyra lägenheter för uthyrning i en vacker trädgårdsmiljö. Lägenheterna bokas direkt med Leila via telefon eller mejl, eller via Airbnb och Booking.com. Nyheter läggs ut på Facebook och Instagram.' where id = 245; -- Jansro Hem & Trädgård
update public.places set short_description = 'Vintage och inredning i gammal lanthandel', description = 'Pellgaardska är en inredningsbutik i Örum som öppnade i juni 2023. Butiken ligger i en gammal skånelänga där Örums lanthandel fanns i 107 år, fram till 1978, och försåg byborna med varor varje dag. Nu finns här vintage och inredning, till exempel stora krukor och säsongens dekorationer. Butiken har öppet främst på helger och under lov, och aktuella öppettider läggs ut i sociala medier. Pellgaardska ligger på Örums bygata, nära Löderup på södra Österlen.' where id = 246; -- Pellgaardska 
update public.places set short_description = 'Gårdshotell med restaurang, konferens och bröllop', description = 'Drakamöllan är ett gårdshotell i en gammal skånegård med anor från 1600-talet, inbäddad i det böljande landskapet nära Degeberga. Gården har korsvirke, kullerstensgångar och buxbomshäckar, och tar emot gäster året runt. Den största skatten beskrivs som tystnaden. Här finns boende, en restaurang, konferens, bröllop och kalas, och Drakamöllan säljer även sina egna kokböcker. Gården ordnar också opera, har ett galleri och ett forum för kultur och vetenskap. Gården är en plats för både livsnjutare och beslutsfattare.' where id = 247; -- Drakamöllan Gårdshotell
update public.places set short_description = 'Vandrarhem på släktgård i Brantevik', description = 'Råkulle Vandrarhem ligger i fiskeläget Brantevik, i en trelängad släktgård med anor från 1700-talet. Gården har tillhört släkten Håkansson i tretton generationer, och här bor familjen själv. Vandrarhemmet är en del av STF och har en familjär atmosfär där gästerna ska känna sig som hemma vid havet. Frukosten får mycket beröm av gästerna. Härifrån kan man cykla, ta ett morgondopp i havet och boka vandringspaket eller en upplevelse med reflekterande skrivande. Rum bokas på hemsidan.' where id = 248; -- Råkulle Vandrarhem
update public.places set short_description = 'Lägenheter på lantgård i Rörum', description = 'Gamla Prästgården ligger i byn Rörum, mitt i det öppna landskapet på Österlen. Här bor man lugnt och lantligt, med Rörums backar, Mandelmanns trädgårdar och havet vid Knäbäckshusen bara några minuter bort. Gården har två lägenheter i den gamla längan: en mindre på 70 kvadratmeter med fyra bäddar och egen uteplats med utsikt över hästhagarna, och en större i två plan på 110 kvadratmeter med sex bäddar, som passar bra för familjer. Lägenheterna bokas via hemsidan.' where id = 250; -- Gamla Prästgården I Rörum
update public.places set short_description = 'Bed and breakfast i Östra Hoby', description = 'Hoby Gård Bed and Breakfast ligger i Östra Hoby kyrkby, mitt emellan Skillinge och Borrby. Härifrån är det bara ett par kilometer till havet, sandstränderna och medeltidsborgen Glimmingehus. Rummen har hög standard, och det finns både rum med eget badrum och rum med delat badrum. Varje morgon serveras en generös frukostbuffé. Hoby Gård passar för den som vill bo lugnt mitt på Österlen men ändå ha nära till både kusten och sevärdheterna. Rum bokas via telefon, mejl eller hemsidan.' where id = 252; -- Hoby Gård Bed & Breakfast
update public.places set short_description = 'Handelsträdgård med floristik utanför Löderup', description = 'Systrarna Lindskogs är en handelsträdgård utanför Löderup som drivs av två trädgårdsälskande systrar. Deras resa började 2013, när de arbetade på en gammal handelsträdgård hos en äldre man med stora kunskaper om odling. I dag har de en egen handelsträdgård med växter, floristik och trädgårdsdesign, och de erbjuder även trädgårdsservice hemma hos kunder. På hösten finns vitlök, sättlök och höstlökar, och på hemsidan finns en vitlöksskola. Inför jul ordnas ett adventsmingel på gården. Handelsträdgården har öppet alla dagar.' where id = 253; -- Systrarna Lindskogs Trädgård & Design
update public.places set short_description = 'Litet hotell i köpmannagård från 1600-talet', description = 'Hotel Kockska Gården är ett litet trestjärnigt hotell mitt i Simrishamn, där husen är låga och gatorna av sten. Hotellet ligger i en korsvirkesgård från sent 1600-tal, som har varit stadens viktigaste köpmannagård ända sedan den byggdes. Den ligger vid de gamla tullarna in till staden. Genom åren har många kända personer bott här, bland andra Carl von Linné under sin skånska resa 1749. Från hotellet är det nära till hamnen, Storgatan och resten av Simrishamn.' where id = 255; -- Hotel Kockska Gården
update public.places set short_description = 'Rosornas hotell i Aspelinska gården', description = 'Hotell Turistgården, även kallat Rosornas hotell, ligger i den historiska Aspelinska gården mitt i Simrishamn. Hotellet kombinerar historisk charm med ett personligt bemötande, där gästerna ska känna sig lite bortskämda. Rummen är personligt inredda och finns i flera olika varianter. Från hotellet är det nära till restauranger, den idylliska hamnen, Gamla stan och järnvägsstationen, vilket gör det till en praktisk utgångspunkt för att upptäcka Österlen även utan bil. Rum bokas direkt via hotellets hemsida.' where id = 256; -- Hotell Turistgården
commit;
